55	void panel(ImDrawList& draw, const OverlayRect& rect, const ShellPalette& p, float radius)
56	{
57	    const ImVec2 min(rect.x, rect.y), max(rect.x + rect.w, rect.y + rect.h);
58	    draw.AddRectFilled(min, max, im_color(p.surface_raised), radius);
59	    // Hairlines are one device pixel, as the shell's own borders are.
60	    draw.AddRect(ImVec2(min.x + 0.5f, min.y + 0.5f), ImVec2(max.x - 0.5f, max.y - 0.5f), im_color(p.border_subtle), radius, 0, 1.f);
