64	bool button(ImDrawList& draw, const char* id, const OverlayRect& rect, const std::string& label, float radius, bool enabled,
65	            const wxColour& fill, const wxColour& fill_hover, const wxColour& text, const wxColour* border, const ShellPalette& p)
66	{
67	    ImGui::SetCursorScreenPos(ImVec2(rect.x, rect.y));
68	    const bool clicked = ImGui::InvisibleButton(id, ImVec2(rect.w, rect.h));
69	    const bool hovered = ImGui::IsItemHovered();
70	    const ImVec2 min(rect.x, rect.y), max(rect.x + rect.w, rect.y + rect.h);
71	    draw.AddRectFilled(min, max, im_color(!enabled ? p.action_disabled : hovered ? fill_hover : fill), radius);
72	    if (border != nullptr && enabled)
73	        draw.AddRect(ImVec2(min.x + 0.5f, min.y + 0.5f), ImVec2(max.x - 0.5f, max.y - 0.5f), im_color(*border), radius, 0, 1.f);
74	    const ImVec2 size = ImGui::CalcTextSize(label.c_str());
75	    draw.AddText(ImVec2(rect.x + std::round((rect.w - size.x) / 2), rect.y + std::round((rect.h - size.y) / 2)),
76	                 im_color(enabled ? text : p.action_disabled_text), label.c_str());
77	    return clicked && enabled;
78	}
