103	// What the pill says: never "no issues" while OrcaSlicer has not looked.
104	std::string status_label(const PrintIssueSnapshot& snapshot, std::size_t blockers)
105	{
106	    if (!snapshot.checked)
107	        return checking_label();
108	    if (snapshot.issues.empty())
109	        return _u8L("No print issues");
110	    const int count = int(snapshot.issues.size());
111	    std::string label = format_wxstr(_L_PLURAL("%1% print issue", "%1% print issues", count), count).ToUTF8().data();
112	    if (blockers != 0)
113	        label += " \xC2\xB7 " + format(_u8L("%1% blocking"), blockers);
114	    return label;
115	}
