158	std::optional<IssueOverlay::Target> IssueOverlay::target_of(const PrintIssue& issue) const
159	{
160	    const Model* model = m_canvas.get_model();
161	    if (model == nullptr || issue.object == 0)
162	        return std::nullopt;
163	    // The object's box in the scene as it is drawn now, so a drag that has
164	    // not been committed to the model still carries the bubble.
165	    BoundingBoxf3 box;
166	    for (const GLVolume* volume : m_canvas.get_volumes().volumes) {
167	        const int object_index = volume->object_idx(), instance_index = volume->instance_idx();
168	        if (object_index < 0 || object_index >= int(model->objects.size()))
169	            continue;
170	        const ModelObject* object = model->objects[object_index];
171	        if (object->id().id != issue.object || instance_index < 0 || instance_index >= int(object->instances.size()))
172	            continue;
173	        if (issue.instance != 0 && object->instances[instance_index]->id().id != issue.instance)
174	            continue;
175	        box.merge(volume->transformed_bounding_box());
176	    }
177	    if (!box.defined)
178	        return std::nullopt;
179	
180	    const Camera& camera = wxGetApp().plater()->get_camera();
181	    const Eigen::Matrix4d to_clip = camera.get_projection_matrix().matrix() * camera.get_view_matrix().matrix();
182	    const std::array<int, 4>& viewport = camera.get_viewport();
183	    const auto project = [&](double x, double y, double z) -> std::optional<ImVec2> {
184	        const Eigen::Vector4d clip = to_clip * Eigen::Vector4d(x, y, z, 1.0);
185	        if (clip.w() <= 1e-9)
186	            return std::nullopt; // behind the camera
187	        return ImVec2(float((0.5 + 0.5 * clip.x() / clip.w()) * viewport[2]), float((0.5 - 0.5 * clip.y() / clip.w()) * viewport[3]));
188	    };
189	
190	    Target target;
191	    float x0 = 0, y0 = 0, x1 = 0, y1 = 0;
192	    for (int corner = 0; corner < 8; ++corner) {
193	        const auto point = project(corner & 1 ? box.max.x() : box.min.x(), corner & 2 ? box.max.y() : box.min.y(),
194	                                   corner & 4 ? box.max.z() : box.min.z());
195	        if (!point)
196	            return std::nullopt;
197	        x0 = corner == 0 ? point->x : std::min(x0, point->x);
198	        y0 = corner == 0 ? point->y : std::min(y0, point->y);
199	        x1 = corner == 0 ? point->x : std::max(x1, point->x);
200	        y1 = corner == 0 ? point->y : std::max(y1, point->y);
201	    }
202	    const auto top = project(box.center().x(), box.center().y(), box.max.z());
203	    if (!top)
204	        return std::nullopt;
205	    target.rect     = {x0, y0, x1 - x0, y1 - y0};
206	    target.anchor_x = top->x;
207	    target.anchor_y = top->y;
208	    return target;
209	}
