211	void IssueOverlay::render()
212	{
213	    m_frame = {};
214	    // Without the token file the app keeps OrcaSlicer's stock presentation,
215	    // which has no overlay; the failure was logged when the tokens were read.
216	    const ShellTheme* theme = brand_theme();
217	    if (theme == nullptr)
218	        return;
219	    const PrintIssueSnapshot& snapshot = m_monitor.snapshot();
220	    const ShellMetrics&       m        = theme->metrics();
221	    const float               scale    = wxGetApp().imgui()->get_style_scaling();
222	    const Size                canvas   = m_canvas.get_canvas_size();
223	    const Style style{m, theme->palette(GUI_App::dark_mode()), scale, float(canvas.get_width()), float(canvas.get_height()),
224	                      std::round(m.space_3 * scale), std::round(m.space_3 * scale), std::round(m.space_2 * scale),
225	                      ImGui::GetTextLineHeight(), std::round(m.space_2 * scale)};
226	
227	    if (!m_selected.empty() && snapshot.find(m_selected) == nullptr)
228	        m_selected.clear(); // the native source stopped reporting it
229	    if (snapshot.issues.empty())
230	        m_list_open = false;
231	
232	    std::size_t blockers = 0;
233	    for (const PrintIssue& issue : snapshot.issues)
234	        blockers += !issue.stale && issue.severity == IssueSeverity::Blocker ? 1 : 0;
235	    m_frame.pill_text = status_label(snapshot, blockers);
236	
237	    const float pill_w     = style.pad + style.dot + style.gap + ImGui::CalcTextSize(m_frame.pill_text.c_str()).x + style.pad;
238	    const float row_height = std::round(m.menu_row.height * scale) + style.line; // two lines of text
239	    const float list_height = m_list_open ? float(snapshot.issues.size()) * row_height + 2 * std::round(m.popover.padding_y * scale) : 0.f;
240	    StatusLayout layout = layout_status(style.canvas_w, style.canvas_h, style.inset, style.gap, pill_w, std::round(m.chip.height * scale),
241	                                        std::round(m.print_issues.list_width * scale), list_height);
242	
243	    draw_pill(style, layout, snapshot);
244	    if (m_list_open)
245	        draw_list(style, layout, snapshot, row_height);
246	    else
247	        draw_notices(style, layout, snapshot); // a docked bubble then starts above them
248	    if (const PrintIssue* issue = m_selected.empty() ? nullptr : snapshot.find(m_selected))
249	        draw_bubble(style, layout, snapshot, *issue);
250	}
