252	// What OrcaSlicer holds that is not a print problem: the outcome of an action,
253	// or work still running. Each is OrcaSlicer's own words in a panel above the
254	// pill, there for as long as OrcaSlicer holds the notification, with a close
255	// button that closes it the way its own did.
256	void IssueOverlay::draw_notices(const Style& s, StatusLayout& layout, const PrintIssueSnapshot& snapshot)
257	{
258	    // Work that is still running is shown in the chat, where it has its bar
259	    // and its Cancel; here are the outcomes only.
260	    std::vector<Notice> results;
261	    for (const Notice& notice : snapshot.notices)
262	        if (notice.route == NoticeRoute::Result)
263	            results.push_back(notice);
264	    // The newest few; an older one returns when a newer one goes.
265	    constexpr std::size_t kShown = 3;
266	    constexpr int         kLines = 4;
267	    const std::size_t first = results.size() > kShown ? results.size() - kShown : 0;
268	    const float       width = std::round(s.m.print_issues.list_width * s.scale);
269	    const float       wrap  = width - 2 * s.pad - s.dot - s.gap - s.line - s.gap;
270	    std::vector<std::string> texts;
271	    std::vector<float>       heights;
272	    for (std::size_t index = first; index < results.size(); ++index) {
273	        texts.push_back(trimmed(results[index].text));
274	        const float text_h = std::min(ImGui::CalcTextSize(texts.back().c_str(), nullptr, false, wrap).y, kLines * s.line);
275	        heights.push_back(s.pad + text_h + s.pad);
276	    }
277	    const std::vector<OverlayRect> rects = stack_notices(layout, s.inset, s.gap, width, heights);
278	
279	    for (std::size_t slot = 0; slot < rects.size(); ++slot) {
280	        const OverlayRect& rect = rects[slot];
281	        if (rect.empty())
282	            continue;
283	        const Notice& notice = results[first + slot];
284	        const wxColour& dot = notice.level == NoticeLevel::Error ? s.p.status_danger :
285	                              notice.level == NoticeLevel::Warning ? s.p.status_warning :
286	                              notice.route == NoticeRoute::Progress ? s.p.text_secondary : s.p.status_success;
287	        const OverlayRect close{rect.x + rect.w - s.pad - s.line, rect.y + s.pad, s.line, s.line};
288	        m_frame.notices.push_back({notice.kind, rect, close});
289	
290	        begin_bare(("##jusprin_notice_" + std::to_string(slot)).c_str(), rect);
291	        ImDrawList& draw = *ImGui::GetWindowDrawList();
292	        panel(draw, rect, s.p, std::round(s.m.radius_container * s.scale));
293	        draw.AddCircleFilled(ImVec2(rect.x + s.pad + s.dot / 2, rect.y + s.pad + s.line / 2), s.dot / 2, im_color(dot));
294	        const ImVec2 text_at(rect.x + s.pad + s.dot + s.gap, rect.y + s.pad);
295	        draw.PushClipRect(text_at, ImVec2(text_at.x + wrap, rect.y + rect.h - s.pad), true);
296	        draw.AddText(ImGui::GetFont(), ImGui::GetFontSize(), text_at, im_color(s.p.text_primary), texts[slot].c_str(), nullptr, wrap);
297	        draw.PopClipRect();
298	        ImGui::SetCursorScreenPos(ImVec2(close.x, close.y));
299	        if (ImGui::InvisibleButton("##close", ImVec2(close.w, close.h)))
300	            after_frame([kind = notice.kind](IssueOverlay& self) { self.m_monitor.dismiss(kind); });
301	        const char*  cross = "\xC3\x97";
302	        const ImVec2 size  = ImGui::CalcTextSize(cross);
303	        draw.AddText(ImVec2(close.x + std::round((close.w - size.x) / 2), close.y + std::round((close.h - size.y) / 2)),
304	                     im_color(ImGui::IsItemHovered() ? s.p.text_primary : s.p.text_secondary), cross);
305	        ImGui::End();
306	    }
307	}
