309	void IssueOverlay::draw_pill(const Style& s, const StatusLayout& layout, const PrintIssueSnapshot& snapshot)
310	{
311	    const OverlayRect& pill = layout.pill;
312	    m_frame.pill = pill;
313	
314	    std::size_t current = 0, blockers = 0;
315	    for (const PrintIssue& issue : snapshot.issues) {
316	        current += issue.stale ? 0 : 1;
317	        blockers += !issue.stale && issue.severity == IssueSeverity::Blocker ? 1 : 0;
318	    }
319	    const wxColour& dot = !snapshot.checked || (current == 0 && !snapshot.issues.empty()) ? s.p.text_secondary :
320	                          snapshot.issues.empty() ? s.p.status_success : blockers != 0 ? s.p.status_danger : s.p.status_warning;
321	
322	    begin_bare("##jusprin_issue_pill", pill);
323	    ImDrawList& draw = *ImGui::GetWindowDrawList();
324	    ImGui::SetCursorScreenPos(ImVec2(pill.x, pill.y));
325	    if (ImGui::InvisibleButton("##pill", ImVec2(pill.w, pill.h)) && !snapshot.issues.empty())
326	        after_frame([](IssueOverlay& self) { self.set_list_open(!self.m_list_open); });
327	    panel(draw, pill, s.p, std::round(s.m.chip.radius * s.scale));
328	    draw.AddCircleFilled(ImVec2(pill.x + s.pad + s.dot / 2, pill.y + pill.h / 2), s.dot / 2, im_color(dot));
329	    const ImVec2 size = ImGui::CalcTextSize(m_frame.pill_text.c_str());
330	    draw.AddText(ImVec2(pill.x + s.pad + s.dot + s.gap, pill.y + std::round((pill.h - size.y) / 2)), im_color(s.p.text_primary),
331	                 m_frame.pill_text.c_str());
332	    ImGui::End();
