369	        const std::string where = (issue.object_name.empty() ? plate_label() : issue.object_name) +
370	                                  (issue.stale ? " \xC2\xB7 " + checking_label() : std::string());
371	        draw.PushClipRect(ImVec2(text_x, min.y), ImVec2(max.x - s.gap, max.y), true);
372	        draw.AddText(ImVec2(text_x, text_y), im_color(s.p.text_primary), first_line(issue.message).c_str());
373	        draw.AddText(ImVec2(text_x, text_y + s.line), im_color(s.p.text_secondary), where.c_str());
