384	void IssueOverlay::draw_bubble(const Style& s, const StatusLayout& layout, const PrintIssueSnapshot& snapshot, const PrintIssue& issue)
385	{
386	    // Every finding on the same object shares the bubble; none is dropped.
387	    // OrcaSlicer names a copy for some findings and only the object for
388	    // others, so the object is what they have in common.
389	    std::vector<const PrintIssue*> group;
390	    for (const PrintIssue& other : snapshot.issues)
391	        if (other.object == issue.object)
392	            group.push_back(&other);
393	    const int group_index = int(std::find(group.begin(), group.end(), &issue) - group.begin());
394	
395	    const std::optional<Target> target = target_of(issue);
396	    const bool in_view = target && target->anchor_x >= 0 && target->anchor_x <= s.canvas_w && target->anchor_y >= 0 &&
397	                         target->anchor_y <= s.canvas_h;
398	    const bool busy    = m_actions.chat_busy && m_actions.chat_busy();
399	    const bool enabled = snapshot.checked && !issue.stale && !busy;
400	
401	    const std::string severity = issue.stale ? checking_label() :
402	                                 issue.severity == IssueSeverity::Blocker ? _u8L("Blocks printing") : _u8L("Warning");
403	    const std::string where    = issue.object == 0 ? plate_label() :
404	                                 issue.object_name + (target && !in_view ? " \xC2\xB7 " + _u8L("out of view") : std::string());
405	    const std::string message  = trimmed(issue.message);
406	    const std::string pager    = group.size() > 1 ? format(_u8L("%1% of %2%"), group_index + 1, group.size()) : std::string();
